from collections import defaultdict, deque

def find_cycle(graph, n):
    for start in range(n):
        visited = [False] * n
        stack = []
        if dfs(graph, start, visited, stack):
            cycle_start = stack.index(start)
            return stack[cycle_start:]
    return None

def dfs(graph, node, visited, stack):
    if visited[node]:
        return node in stack
    visited[node] = True
    stack.append(node)
    for neighbor in graph[node]:
        if dfs(graph, neighbor, visited, stack):
            return True
    stack.pop()
    return False

